body.script:
    import { initializeApp } from "https://www.gstatic.com/firebasejs/10.12.2/firebase-app.js";
    import { getAuth, onAuthStateChanged } from "https://www.gstatic.com/firebasejs/10.12.2/firebase-auth.js";
    import { getFirestore, doc, getDoc } from "https://www.gstatic.com/firebasejs/10.12.2/firebase-firestore.js";

    // 1. FIREBASE CONFIGURATION
   const firebaseConfig = {
  apiKey: "AIzaSyBUhNhYvuo_FTvZ5RZR6Gn-4hsUY21S0XE",
  authDomain: "ghotimarket.firebaseapp.com",
  databaseURL: "https://ghotimarket-default-rtdb.firebaseio.com",
  projectId: "ghotimarket",
  storageBucket: "ghotimarket.firebasestorage.app",
  messagingSenderId: "481257644093",
  appId: "1:481257644093:web:0dfc3699d6b3c86afeca54",
  measurementId: "G-4SR8V2EKC1"
};
    // Initialize Firebase Services
    const app = initializeApp(firebaseConfig);
    const auth = getAuth(app);
    const db = getFirestore(app);

    // DOM Elements References
    const stateLoading = document.getElementById('state-loading');
    const stateActiveSitemap = document.getElementById('state-active-sitemap');
    const stateNoDomain = document.getElementById('state-no-domain');
    const stateAuthRequired = document.getElementById('state-auth-required');
    const stateShopNotFound = document.getElementById('state-shop-not-found');
    const stateError = document.getElementById('state-error');

    const displayDomainEl = document.getElementById('display-domain');
    const sitemapUrlInput = document.getElementById('sitemap-url-input');
    const sitemapPreviewLink = document.getElementById('sitemap-preview-link');
    const btnOpenSitemap = document.getElementById('btn-open-sitemap');
    const btnCopy = document.getElementById('btn-copy');
    const btnCopyIcon = document.getElementById('btn-copy-icon');
    const btnCopyText = document.getElementById('btn-copy-text');
    const btnRetry = document.getElementById('btn-retry');

    let currentSitemapUrl = "";
    let currentUserUID = null;

    // Helper: Switch UI States Cleanly
    function showState(activeStateEl) {
      [stateLoading, stateActiveSitemap, stateNoDomain, stateAuthRequired, stateShopNotFound, stateError].forEach(el => {
        if (el) el.classList.add('hidden');
      });
      if (activeStateEl) {
        activeStateEl.classList.remove('hidden');
      }
    }

    // 2. DOMAIN NORMALIZATION FUNCTION
    function normalizeDomain(rawDomain) {
      if (!rawDomain || typeof rawDomain !== 'string') return '';

      let clean = rawDomain.trim().toLowerCase();

      // Remove protocol prefix (http://, https://)
      clean = clean.replace(/^https?:\/\//i, '');

      // Remove www.
      clean = clean.replace(/^www\./i, '');

      // Remove paths, query parameters, or hashes (e.g., myshop.com/path?a=1)
      clean = clean.split('/')[0].split('?')[0].split('#')[0];

      // Strip any non-domain safe characters (allows alphanumeric, hyphens, and dots)
      clean = clean.replace(/[^a-z0-9.-]/gi, '');

      return clean;
    }

    // 3. LOAD SHOP DATA FROM FIRESTORE
    async function loadShopData(uid) {
      showState(stateLoading);
      try {
        const shopRef = doc(db, "shops", uid);
        const shopSnap = await getDoc(shopRef);

        if (!shopSnap.exists()) {
          showState(stateShopNotFound);
          return;
        }

        const shopData = shopSnap.data();
        const rawDomain = shopData ? shopData.customDomain : null;
        const normalizedDomain = normalizeDomain(rawDomain);

        if (normalizedDomain && normalizedDomain.length > 3) {
          // Construct Clean HTTPS Sitemap URL
          currentSitemapUrl = `https://${normalizedDomain}/sitemap.xml`;

          // Update UI Elements
          displayDomainEl.textContent = normalizedDomain;
          sitemapUrlInput.value = currentSitemapUrl;
          sitemapPreviewLink.href = currentSitemapUrl;
          sitemapPreviewLink.textContent = currentSitemapUrl;
          btnOpenSitemap.href = currentSitemapUrl;

          showState(stateActiveSitemap);
        } else {
          // Custom domain missing or empty
          showState(stateNoDomain);
        }

      } catch (err) {
        console.error("Error loading shop data from Firestore:", err);
        showState(stateError);
      }
    }

    // 4. AUTH STATE OBSERVER
    onAuthStateChanged(auth, (user) => {
      if (user) {
        currentUserUID = user.uid;
        loadShopData(currentUserUID);
      } else {
        currentUserUID = null;
        showState(stateAuthRequired);
      }
    });

    // 5. COPY TO CLIPBOARD HANDLER
    btnCopy.addEventListener('click', async () => {
      if (!currentSitemapUrl) return;

      let copiedSuccess = false;

      // Primary: Modern Clipboard API
      if (navigator.clipboard && window.isSecureContext) {
        try {
          await navigator.clipboard.writeText(currentSitemapUrl);
          copiedSuccess = true;
        } catch (err) {
          console.warn("Clipboard API failed, attempting fallback copy method.", err);
        }
      }

      // Fallback: execCommand('copy')
      if (!copiedSuccess) {
        try {
          sitemapUrlInput.select();
          sitemapUrlInput.setSelectionRange(0, 99999); // Mobile
          copiedSuccess = document.execCommand('copy');
          window.getSelection().removeAllRanges();
        } catch (err) {
          console.error("Fallback copy failed:", err);
        }
      }

      if (copiedSuccess) {
        showToast("সাইটম্যাপ লিংক কপি হয়েছে!", "success");

        // Button UI Feedback
        btnCopy.classList.add('btn-copied');
        btnCopyIcon.textContent = "✓";
        btnCopyText.textContent = "Copied";

        setTimeout(() => {
          btnCopy.classList.remove('btn-copied');
          btnCopyIcon.textContent = "📋";
          btnCopyText.textContent = "Copy Sitemap URL";
        }, 2500);
      } else {
        showToast("কপি করা যায়নি, ম্যানুয়ালি কপি করুন।", "error");
      }
    });

    // Retry Button Handler
    if (btnRetry) {
      btnRetry.addEventListener('click', () => {
        if (currentUserUID) {
          loadShopData(currentUserUID);
        } else {
          location.reload();
        }
      });
    }

    // 6. CUSTOM TOAST NOTIFICATION SYSTEM
    function showToast(message, type = 'success') {
      const toast = document.getElementById('app-toast');
      const toastIcon = document.getElementById('toast-icon');
      const toastMsg = document.getElementById('toast-message');

      if (!toast || !toastMsg) return;

      toastMsg.textContent = message;

      if (type === 'success') {
        toastIcon.textContent = "✓";
      } else {
        toastIcon.textContent = "⚠️";
      }

      toast.className = `toast ${type} active`;

      setTimeout(() => {
        toast.classList.remove('active');
      }, 3000);
    }
